contracts/library/Pausable.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

abstract contract Pausable {
    event Paused(address account);
    event Unpaused(address account);

    bool private _paused;

    modifier whenNotPaused() {
        _requireNotPaused();
        _;
    }

    modifier whenPaused() {
        _requirePaused();
        _;
    }

    function paused() public view virtual returns (bool) {
        return _paused;
    }

    function _requireNotPaused() internal view virtual {
        require(!paused(), "Pausable");
    }

    function _requirePaused() internal view virtual {
        require(paused(), "Pausable");
    }

    function _pause() internal virtual whenNotPaused {
        _paused = true;
        emit Paused(msg.sender);
    }

    function _unpause() internal virtual whenPaused {
        _paused = false;
        emit Unpaused(msg.sender);
    }
}

contracts/interfaces/IRouter.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.3;

import "./IKokonutSwapPool.sol";

interface IRouter {
    event SwapWithPath(
        address user,
        address inputToken,
        uint256 inputAmount,
        address outputToken,
        uint256 outputAmount
    );

    function getPrice(address[] calldata path, uint256[3][] calldata swapParams) external view returns (uint256);

    function getDy(
        address[] calldata path,
        uint256[3][] calldata swapParams,
        uint256 amount
    ) external view returns (uint256[] memory);

    function getDyWithoutFee(
        address[] calldata path,
        uint256[3][] calldata swapParams,
        uint256 amount
    ) external view returns (uint256[] memory);

    function swapWithPath(
        address[] calldata path,
        uint256[3][] calldata swapParams,
        uint256 amount,
        uint256 minAmount
    ) external payable returns (uint256[] memory);

    function addLiquidity(
        address pool,
        uint256 poolType,
        uint256[] calldata amounts,
        uint256 minMintAmount
    ) external payable returns (uint256);
}

