pragma solidity ^0.8.3;

import "../library/Pausable.sol";
import "../library/Ownable.sol";

abstract contract ZKokonutAccess is Ownable, Pausable {
    function _initializeZKokonutAccess(address owner_) internal {
        _transferOwnership(owner_);
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }
}

contracts/interfaces/IStableSwap.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.3;

import "./IKokonutSwapPool.sol";

interface IStableSwap is IKokonutSwapPool {
    event AddLiquidity(
        address indexed provider,
        uint256[] tokenAmounts,
        uint256[] feeAmounts,
        uint256 invariant,
        uint256 tokenSupply
    );
    event RemoveLiquidityOne(
        address indexed provider,
        uint256 i,
        uint256 tokenAmount,
        uint256 feeAmount,
        uint256 tokenSupply
    );
    event RemoveLiquidityImbalance(
        address indexed provider,
        uint256[] tokenAmounts,
        uint256[] fees,
        uint256 invariant,
        uint256 tokenSupply
    );
    event CommitNewOwner(uint256 indexed deadline, address indexed owner);
    event CommitNewFee(uint256 indexed deadine, uint256 fee, uint256 adminFee);
    event NewFee(uint256 fee, uint256 adminFee);
    event RampA(uint256 oldA, uint256 newA, uint256 initialTime, uint256 futureTime);
    event StopRampA(uint256 A, uint256 t);

    function APrecise() external view returns (uint256);

    function getLpPrice(uint256 i) external view returns (uint256);

    function getDx(uint256 i, uint256 j, uint256 dy) external view returns (uint256);

    function getDyUnderlying(uint256 i, uint256 j, uint256 dx) external view returns (uint256, uint256);

    function addLiquidity(
        uint256[] calldata amounts,
        uint256 minMintAmount
    ) external returns (uint256, uint256[] memory);

    function removeLiquidityImbalance(uint256[] calldata amounts, uint256 maxBurnAmount) external returns (uint256);

    function removeLiquidityOneCoin(
        uint256 tokenAmount,
        uint256 i,
        uint256 minAmount
    ) external returns (uint256, uint256);

    function calcDeposit(uint256[] calldata amounts) external view returns (uint256, uint256[] memory);

    function calcWithdraw(uint256[] calldata amounts) external view returns (uint256, uint256);

    function calcWithdrawOneCoin(uint256 tokenAmount, uint256 i) external view returns (uint256, uint256);

    function rampA(uint256 _futureA, uint256 _futureTime) external;

    function stopRampA() external;

    function commitNewFee(uint256 newFee, uint256 newAdminFee) external;

    function applyNewFee() external;

    function revertNewParameters() external;

    function transferOwnership(address newOwner) external;

    function applyTransferOwnership() external;

    function revertTransferOwnership() external;

    function adminBalances(uint256 i) external view returns (uint256);

    function adminBalanceList() external view returns (uint256[] memory balances_);

    function withdrawAdminFees(address recipient) external;

    function donateAdminFees() external;

    function initialA() external view returns (uint256);

    function futureA() external view returns (uint256);

    function initialATime() external view returns (uint256);

    function futureATime() external view returns (uint256);

    function adminActionsDeadline() external view returns (uint256);

    function transferOwnershipDeadline() external view returns (uint256);

    function futureFee() external view returns (uint256);

    function futureAdminFee() external view returns (uint256);

    function futureOwner() external view returns (address);
}

