contracts/Router.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.3;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "./interfaces/IRouter.sol";
import "./interfaces/IWETH.sol";
import "./interfaces/ICryptoSwap2Pool.sol";
import "./interfaces/IMetaPool.sol";
import "./library/ReentrancyGuard.sol";
import "./utils/ZKokonutAccess.sol";

contract Router is ReentrancyGuard, IRouter {
    using SafeERC20 for IERC20;

    address private immutable WETH_ADDRESS;

    mapping(address => mapping(address => bool)) public isApproved;

    constructor(address wethAddress) {
        WETH_ADDRESS = wethAddress;
    }

    function getPrice(address[] calldata path, uint256[3][] calldata swapParams) external view returns (uint256 price) {
        address inputToken = path[0];
        if (inputToken == address(0)) inputToken = WETH_ADDRESS;
        price = 10 ** 18;

        for (uint256 i = 1; i < path.length / 2 + 1; ++i) {
            // 4 rounds of iteration to perform up to 4 swaps
            address swap = path[i * 2 - 1];
            if (swap == address(0)) {
                break;
            }
            address outputToken = path[i * 2];
            if (outputToken == address(0)) outputToken = WETH_ADDRESS;
            uint256[3] calldata params = swapParams[i - 1]; // i, j, swap type
            _checkSwapParams(inputToken, outputToken, swap, params);

            if (params[2] == 1) {
                price = (price * IStableSwap(swap).getPrice(params[0], params[1])) / 10 ** 18;
            } else if (params[2] == 2) {
                price = (price * IMetaPool(swap).getPrice(params[0], params[1])) / 10 ** 18;
            } else if (params[2] == 3) {
                price = (price * ICryptoSwap2Pool(swap).getPrice(params[0], params[1])) / 10 ** 18;
            } else {
                revert("Bad swap type");
            }

            inputToken = outputToken;
        }
    }

    function getDy(
        address[] calldata path,
        uint256[3][] calldata swapParams,
        uint256 amount
    ) external view returns (uint256[] memory) {
        return _getDy(path, swapParams, amount, false);
    }

    function getDyWithoutFee(
        address[] calldata path,
        uint256[3][] calldata swapParams,
        uint256 amount
    ) external view returns (uint256[] memory) {
        return _getDy(path, swapParams, amount, true);
    }

    /// @notice Perform up to multiple swaps in a single transaction
    /// @dev Routing and swap params must be determined off-chain. This
    ///      functionality is designed for gas efficiency over ease-of-use.
    /// @param path Array of [initial token, pool, token, pool, token, ...]
    ///               The array is iterated until a pool address of 0x00, then the last
    ///               given token is transferred to `_receiver`
    /// @param swapParams Multidimensional array of [i, j, swap type] where i and j are the correct
    ///                     values for the n'th pool in `_route`. The swap type should be 1 for
    ///                     a stableswap `exchange`, 2 for stableswap `exchange_underlying` and 3
    ///                     for a cryptoswap `exchange`.
    /// @param amount The amount of input token.
    /// @return outputs The array of the amount of all output tokens through the path
    function _getDy(
        address[] calldata path,
        uint256[3][] calldata swapParams,
        uint256 amount,
        bool withoutFee
    ) internal view returns (uint256[] memory outputs) {
        address inputToken = path[0];
        if (inputToken == address(0)) inputToken = WETH_ADDRESS;
        address outputToken;
        outputs = new uint256[](path.length / 2);

        for (uint256 i = 1; i < path.length / 2 + 1; ++i) {
            // 4 rounds of iteration to perform up to 4 swaps
            address swap = path[i * 2 - 1];
            if (swap == address(0)) {
                break;
            }
            outputToken = path[i * 2];
            if (outputToken == address(0)) outputToken = WETH_ADDRESS;
            uint256[3] calldata params = swapParams[i - 1]; // i, j, swap type
            _checkSwapParams(inputToken, outputToken, swap, params);

            uint256 dy;
            uint256 dyFee;
            if (params[2] == 1) {
                (dy, dyFee) = IStableSwap(swap).getDy(params[0], params[1], amount);
            } else if (params[2] == 2) {
                (dy, dyFee) = IMetaPool(swap).getDyUnderlying(params[0], params[1], amount);
            } else if (params[2] == 3) {
                (dy, dyFee) = ICryptoSwap2Pool(swap).getDy(params[0], params[1], amount);
            } else {
                revert("Bad swap type");
            }
            outputs[i - 1] = withoutFee ? dy + dyFee : dy;

            // sanity check, if the routing data is incorrect we will have a 0 balance and that is bad
            require(amount != 0, "Received nothing");

            // if there is another swap, the output token becomes the input for the next round
            amount = outputs[i - 1];
            inputToken = outputToken;
        }
    }

    /// @notice Perform up to multiple swaps in a single transaction
    /// @dev Routing and swap params must be determined off-chain. This
    ///      functionality is designed for gas efficiency over ease-of-use.
    /// @param path Array of [initial token, pool, token, pool, token, ...]
    ///               The array is iterated until a pool address of 0x00, then the last
    ///               given token is transferred to `msg.sender`
    /// @param swapParams Multidimensional array of [i, j, swap type] where i and j are the correct
    ///                     values for the n'th pool in `_route`. The swap type should be 1 for
    ///                     a stableswap `exchange`, 2 for stableswap `exchange_underlying` and 3
    ///                     for a cryptoswap `exchange`.
    /// @param amount The amount of input token.
    /// @param minAmount The minimum amount received after the final swap.
    /// @return outputs The array of the amount of all output tokens through the path
    function swapWithPath(
        address[] calldata path,
        uint256[3][] calldata swapParams,
        uint256 amount,
        uint256 minAmount
    ) external payable nonReentrant returns (uint256[] memory outputs) {
        address curInputToken = path[0];
        address curOutputToken = address(0);
        uint256 inputAmount = amount;
        outputs = new uint256[](path.length / 2);

        if (curInputToken == address(0)) {
            if (msg.value > amount) {
                IWETH(WETH_ADDRESS).deposit{value: amount}();
                (bool success, ) = msg.sender.call{value: msg.value - amount}("");
                require(success);
            } else {
                IWETH(WETH_ADDRESS).deposit{value: msg.value}();
                if (msg.value < amount) {
                    IERC20(WETH_ADDRESS).safeTransferFrom(msg.sender, address(this), amount - msg.value);
                }
            }
        } else {
            require(msg.value == 0);
            IERC20(curInputToken).safeTransferFrom(msg.sender, address(this), amount);
        }

        for (uint256 i = 1; i < path.length / 2 + 1; ++i) {
            // 4 rounds of iteration to perform up to 4 swaps
            address swap = path[i * 2 - 1];
            if (swap == address(0)) {
                break;
            }
            if (curInputToken == address(0)) {
                curInputToken = WETH_ADDRESS;
            }
            curOutputToken = path[i * 2];
            uint256[3] calldata params = swapParams[i - 1]; // i, j, swap type
            _checkSwapParams(curInputToken, curOutputToken == address(0) ? WETH_ADDRESS : curOutputToken, swap, params);
            _ensureApproved(swap, curInputToken);

            uint256 dy;
            if (params[2] == 1) {
                (dy, ) = IStableSwap(swap).exchange(params[0], params[1], amount, 0, new bytes(0));
            } else if (params[2] == 2) {
                (dy, ) = IMetaPool(swap).exchangeUnderlying(params[0], params[1], amount, 0);
            } else if (params[2] == 3) {
                (dy, ) = ICryptoSwap2Pool(swap).exchange(params[0], params[1], amount, 0, new bytes(0));
            } else {
                revert("Bad swap type");
            }
            outputs[i - 1] = dy;

            // update the amount received
            if (curOutputToken == address(0)) {
                amount = IERC20(WETH_ADDRESS).balanceOf(address(this));
            } else {
                amount = IERC20(curOutputToken).balanceOf(address(this));
            }

            // sanity check, if the routing data is incorrect we will have a 0 balance and that is bad
            require(amount != 0, "Received nothing");

            // if there is another swap, the output token becomes the input for the next round
            curInputToken = curOutputToken;
        }

        // validate the final amount received
        require(amount >= minAmount);
        require(curOutputToken == path[path.length - 1], "wrong output");

        // transfer the final token to the msg.sender
        if (curOutputToken == address(0)) {
            IWETH(WETH_ADDRESS).withdraw(amount);
            (bool success, ) = msg.sender.call{value: amount}("");
            require(success);
        } else {
            IERC20(curOutputToken).safeTransfer(msg.sender, amount);
        }

        emit SwapWithPath(msg.sender, path[0], inputAmount, curOutputToken, amount);
    }

    function addLiquidity(
        address pool,
        uint256 poolType,
        uint256[] memory amounts,
        uint256 minMintAmount
    ) external payable nonReentrant returns (uint256 mintAmount) {
        uint256 nCoins = IKokonutSwapPool(pool).N_COINS();
        require(amounts.length == nCoins, "wrong length");
        for (uint256 i = 0; i < nCoins; ++i) {
            address coin = IKokonutSwapPool(pool).coins(i);
            if (amounts[i] > 0) {
                IERC20(coin).safeTransferFrom(msg.sender, address(this), amounts[i]);
            }
            if (coin == WETH_ADDRESS && msg.value > 0) {
                amounts[i] += msg.value;
                IWETH(WETH_ADDRESS).deposit{value: msg.value}();
            }
            if (amounts[i] > 0) {
                _ensureApproved(pool, coin);
            }
        }
        address lpToken = IKokonutSwapPool(pool).token();

        if (poolType == 1) {
            (mintAmount, ) = IStableSwap(pool).addLiquidity(amounts, minMintAmount);
        } else if (poolType == 2) {
            (mintAmount, ) = IMetaPool(pool).addLiquidity(amounts, minMintAmount);
        } else if (poolType == 3) {
            (mintAmount, ) = ICryptoSwap2Pool(pool).addLiquidity(amounts, minMintAmount);
        } else {
            revert("Bad swap type");
        }
        IERC20(lpToken).safeTransfer(msg.sender, mintAmount);
    }

    function _ensureApproved(address pool, address coin) internal {
        if (!isApproved[coin][pool]) {
            // approve the pool to transfer the input token
            IERC20(coin).safeApprove(pool, type(uint256).max);
            isApproved[coin][pool] = true;
        }
    }

    function _checkSwapParams(
        address inputToken,
        address outputToken,
        address swap,
        uint256[3] calldata swapParam
    ) internal view {
        require(IKokonutSwapPool(swap).coins(swapParam[0]) == inputToken, "swap param");
        require(IKokonutSwapPool(swap).coins(swapParam[1]) == outputToken, "swap param");
    }

    receive() external payable {}
}

